660	function formatResourceIds(store: Store, ids: string[]): string {
661	  return ids
662	    .map((id) => {
663	      const r = store.resources.find((x) => x.id === id);
664	      return r ? `${id}（${r.name}）` : id;
665	    })
666	    .join('、');
667	}
