669	// 校验请求中的资源标识：去重、检查存在性；返回按标识排序的集合
670	function resolveResourceIds(store: Store, rawIds: string[]): string[] {
671	  const problems: string[] = [];
672	  const seen = new Set<string>();
673	  const dupes: string[] = [];
674	  for (const id of rawIds) {
675	    if (seen.has(id)) {
676	      if (!dupes.includes(id)) dupes.push(id);
677	    }
678	    seen.add(id);
679	  }
680	  if (dupes.length > 0) problems.push(`资源重复指定: ${dupes.join('、')}`);
681	
682	  const unknown = [...seen].filter((id) => !store.resources.some((r) => r.id === id)).sort();
683	  if (unknown.length > 0) problems.push(`未知资源标识: ${unknown.join('、')}`);
684	
685	  if (problems.length > 0) throw new BizError(problems.join('\n'));
686	  return [...seen].sort();
687	}
