739	interface CoverageGap {
740	  id: string;
741	  r: ResourceRec;
742	  closures: ClosureRec[]; // 与该区间重叠的相关有效停用（按开始时间、标识排序）
743	}
744	
745	// 找出实际可用时间（开放扣除有效停用）不能完整覆盖 [startMin, endMin) 的资源
746	function findCoverageGaps(
747	  store: Store,
748	  ids: string[],
749	  startMin: number,
750	  endMin: number,
751	): CoverageGap[] {
752	  const gaps: CoverageGap[] = [];
753	  for (const id of ids) {
754	    const r = store.resources.find((x) => x.id === id)!;
755	    if (isFullyCovered(availableSegmentsOf(store, r), startMin, endMin)) continue;
756	    const closures = activeClosuresOf(store, id).filter((c) => {
757	      const cs = parseDateTime(c.start, '停用开始时间');
758	      const ce = parseDateTime(c.end, '停用结束时间');
759	      return cs < endMin && startMin < ce;
760	    });
761	    gaps.push({id, r, closures});
762	  }
763	  return gaps;
764	}
765	
766	// 开放不足资源的统一展示：资源行 + 相关有效停用（标识与时间）
767	function gapLines(gaps: CoverageGap[], indent: string): string[] {
768	  const lines: string[] = [];
769	  for (const g of gaps) {
770	    lines.push(`${indent}- ${g.id}（${g.r.name}）`);
771	    for (const c of g.closures) {
772	      lines.push(`${indent}  相关有效停用: ${c.id}（${c.start} → ${c.end}）`);
773	    }
774	  }
775	  return lines;
776	}
777	
778	// 校验每个资源的实际可用时间都能完整覆盖 [startMin, endMin)
779	function assertOpenCoverage(store: Store, ids: string[], startMin: number, endMin: number): void {
780	  const failing = findCoverageGaps(store, ids, startMin, endMin);
781	  if (failing.length > 0) {
782	    throw new BizError(
783	      '开放时间不足，以下资源的实际可用时间（开放区间扣除有效停用）不能完整覆盖预约区间：\n' +
784	        gapLines(failing, '').join('\n'),
785	    );
786	  }
787	}
