856	interface ParsedFlags {
857	  values: Map<string, string[]>;
858	  positionals: string[];
859	}
860	
861	// 子命令选项解析：allowed 中列出的选项均需带值；multi 中的选项可重复
862	function parseFlags(args: string[], allowed: string[], multi: string[] = []): ParsedFlags {
863	  const allowedSet = new Set(allowed);
864	  const multiSet = new Set(multi);
865	  const values = new Map<string, string[]>();
866	  const positionals: string[] = [];
867	
868	  const takeValue = (key: string, inline: string | undefined, index: number): [string, number] => {
869	    if (inline !== undefined) return [inline, index];
870	    const v = args[index + 1];
871	    if (v === undefined || v.startsWith('-')) {
872	      throw new UsageError(`选项 --${key} 缺少值`);
873	    }
874	    return [v, index + 1];
875	  };
876	
877	  for (let i = 0; i < args.length; i++) {
878	    const a = args[i];
879	    if (a.startsWith('--')) {
880	      let key: string;
881	      let inline: string | undefined;
882	      const eq = a.indexOf('=');
883	      if (eq >= 0) {
884	        key = a.slice(2, eq);
885	        inline = a.slice(eq + 1);
886	      } else {
887	        key = a.slice(2);
888	      }
889	      if (!allowedSet.has(key)) throw new UsageError(`未知选项: --${key}`);
890	      let v: string;
891	      [v, i] = takeValue(key, inline, i);
892	      if (v === '') throw new UsageError(`选项 --${key} 的值不能为空`);
893	      if (!multiSet.has(key) && values.has(key)) {
894	        throw new UsageError(`选项 --${key} 只能指定一次`);
895	      }
896	      const list = values.get(key) ?? [];
897	      list.push(v);
898	      values.set(key, list);
899	    } else if (a.startsWith('-') && a !== '-') {
900	      throw new UsageError(`未知参数: ${a}`);
901	    } else {
902	      positionals.push(a);
903	    }
904	  }
905	  return {values, positionals};
906	}
