1012	  if (!booking) throw new BizError(`未知预约标识: ${id}`);
1013	  if (booking.status === 'cancelled') {
1014	    throw new BizError(`预约 ${id} 已取消，不能改期`);
1015	  }
1016	
1017	  const hasTime = values.has('start') || values.has('end');
1018	  const hasResource = values.has('resource');
1019	  if (!hasTime && !hasResource) {
1020	    throw new BizError('未指定任何改动：请提供 --start/--end 修改时间，或 --resource 替换资源（可同时提供）');
1021	  }
1022	
1023	  const startRaw = values.get('start')?.[0] ?? booking.start;
1024	  const endRaw = values.get('end')?.[0] ?? booking.end;
1025	  const startMin = parseDateTime(startRaw, '预约开始时间');
1026	  const endMin = parseDateTime(endRaw, '预约结束时间');
