1979	// 受阻项报告：固定项列开放不足与全部阻挡（含本轮后项产生的预约——
1980	// 本函数在全部选择完成后按最终占用渲染）；弹性项列窗口内全部最大共同空闲区间及分钟数
1981	function renderBlocked(
1982	  store: Store,
1983	  w: WaitlistRec,
1984	  fromWaitlistByBooking: Map<string, string>,
1985	): string {
1986	  const lines = [`- 继续等待 ${w.id}（${WAITLIST_KIND_LABEL[w.kind]}）：${renderWaitlistRequest(w)}`];
1987	
1988	  if (w.kind === 'fixed') {
1989	    const startMin = parseDateTime(w.start, '候补开始时间');
1990	    const endMin = parseDateTime(w.end, '候补结束时间');
1991	    const gaps = findCoverageGaps(store, w.resourceIds, startMin, endMin);
1992	    if (gaps.length > 0) {
1993	      lines.push('    开放不足资源:');
1994	      lines.push(...gapLines(gaps, '      '));
1995	    }
1996	    const conflicts = findConflicts(store, w.resourceIds, startMin, endMin);
1997	    if (conflicts.length > 0) {
1998	      lines.push('    冲突预约（共同资源时间重叠）:');
1999	      for (const c of conflicts) {
2000	        const fromId = fromWaitlistByBooking.get(c.booking.id);
2001	        const note = fromId ? `（本轮新预约，兑现自候补 ${fromId}）` : '';
2002	        lines.push(
2003	          `      - ${c.booking.id}${note}（${c.booking.start} → ${c.booking.end}）` +
2004	            `：共同资源 ${formatResourceIds(store, c.shared)}`,
2005	        );
2006	      }
2007	    }
2008	    return lines.join('\n');
2009	  }
2010	
2011	  // 弹性项：按最终安排列出窗口内全部最大共同空闲区间及分钟数（按开始时间排序）
2012	  const free = flexFreeSegments(store, w);
2013	  lines.push('    窗口内全部最大共同空闲区间（全部资源同时连续可用，按开始时间排序）:');
2014	  if (free.length === 0) {
2015	    lines.push('      （空集：窗口内全部资源没有任何共同空闲区间，无法容纳所需连续时长）');
2016	  } else {
2017	    lines.push(...renderMinuteSegments(free, '      '));
2018	  }
2019	  return lines.join('\n');
2020	}
