const parseSnapshot = (value: unknown, sat: string): Snapshot => {
  if (typeof value !== 'object' || value === null || Array.isArray(value)) bad(`${sat} 必须是对象`);
  const snap = value as Record<string, unknown>;
  if (typeof snap.start !== 'string' || typeof snap.end !== 'string') bad(`${sat} 起止时间必须是字符串`);
  const s = parseDateTime(snap.start, `${sat}.start`);
  const e = parseDateTime(snap.end, `${sat}.end`);
  if (e <= s) bad(`${sat} 结束必须晚于开始`);
  if (!Array.isArray(snap.resourceIds) || snap.resourceIds.length === 0) bad(`${sat}.resourceIds 必须是非空数组`);
  const seen = new Set<string>();
  (snap.resourceIds as unknown[]).forEach((rid) => {
    if (typeof rid !== 'string' || !resourceIds.has(rid)) bad(`${sat} 引用了未知资源: ${String(rid)}`);
    if (seen.has(rid)) bad(`${sat} 资源重复: ${rid}`);
    seen.add(rid);
  });
  return {start: snap.start, end: snap.end, resourceIds: [...seen].sort()};
};
